func runAll(ctx context.Context, jobs []func() error, limit int) error {
	active := make(chan struct{}, limit)
	for _, job := range jobs {
		select {
		case active <- struct{}{}:
		case <-ctx.Done():
			return ctx.Err()
		}
		if err := job(); err != nil {
			return err
		}
		<-active
	}
	return nil
}

