func joinLines(lines []string) string {
	var sb strings.Builder
	for _, line := range lines {
		sb.WriteString(line)
		sb.WriteByte('\n')
	}
	return sb.String()
}

func renderTable(rows []Row) (string, string) {
	head, body := &strings.Builder{}, &strings.Builder{}
	head.WriteString(rows[0].Header())
	for _, row := range rows {
		body.WriteString(row.Line())
	}
	return head.String(), body.String()
}

public final class CsvLine {
    public static String join(List<String> cells) {
        StringBuilder builder = new StringBuilder();
        for (String cell : cells) {
            if (builder.length() > 0) {
                builder.append(',');
            }
            builder.append(cell);
        }
        return builder.toString();
    }
}

